using MultiFPS.Gameplay.RiftCombat;
using UnityEngine;
using UnityEngine.UI;
namespace ROM.UI.Sprint01 {
public sealed class RiftTalentDetailCard:MonoBehaviour {
 RiftTalentTreeView tree;RectTransform content;Text title,rank,current,next,cost,requirements,state;Image icon;Button learn;int lastIndex=-1;
 public string CurrentText=>current?current.text:"";public string NextText=>next?next.text:"";
 public static RiftTalentDetailCard Create(Transform parent,float x,RiftTalentTreeView owner){var root=RiftSkillStyle.Panel(parent,"Selected talent card",x,0,344,740,.65f);RiftWidgets.Image(root,"Rift accent",0,0,3,740,new Color(.38f,.26f,.56f,.65f));var card=root.gameObject.AddComponent<RiftTalentDetailCard>();card.tree=owner;card.icon=RiftWidgets.Image(root,"Selected talent icon",116,18,112,112,Color.white);card.icon.preserveAspect=true;card.content=RiftWidgets.ScrollArea(root,"Talent facts",22,146,300,478,750);card.title=card.Label(24,new Color(.94f,.8f,.55f));card.rank=card.Label(17,RiftWidgets.Muted);card.current=card.Label(20,RiftWidgets.White);card.next=card.Label(20,new Color(.95f,.77f,.44f));card.cost=card.Label(20,RiftWidgets.White);card.requirements=card.Label(18,RiftWidgets.Muted);card.state=card.Label(18,RiftWidgets.Muted);card.learn=RiftSkillStyle.Button(root,"APRENDER",22,664,300,50,owner.LearnSelected);return card;}
 Text Label(int size,Color color)=>RiftWidgets.Label(content,"",0,0,292,40,size,color);
 void Place(Text label,string value,ref float y){label.text=value;float height=Mathf.Max(26,label.preferredHeight+4);label.rectTransform.anchoredPosition=new Vector2(0,-y);label.rectTransform.sizeDelta=new Vector2(292,height);y+=height+13;}
 public void Show(WarriorTalent talent,int index,int value,bool available,string reason,WarriorProgressionDefinition tuning){var player=MultiFPS.UI.ClientFrontend.ClientPlayerInstance;var combat=player?player.GetComponent<AbilityController>():null;int[] sources={1,7,7,6,3,6,1,2,5};icon.sprite=combat?combat.Definition(sources[index]).Icon:null;float y=0;Place(title,talent.Name,ref y);Place(rank,"RANGO "+value+" / "+talent.MaximumRank,ref y);Place(current,"ACTUAL\n"+RiftTalentPresentation.Effect(index,value),ref y);Place(next,"SIGUIENTE\n"+(value>=talent.MaximumRank?"Rango máximo":RiftTalentPresentation.Effect(index,value+1)),ref y);Place(cost,"COSTO  "+(value>=talent.MaximumRank?"—":"1 punto"),ref y);Place(requirements,"Nivel "+talent.RequiredLevel+"\n"+(talent.Parent<0?"Sin talento previo":tuning.Talents[talent.Parent].Name+" "+tuning.Talents[talent.Parent].MaximumRank+"/"+tuning.Talents[talent.Parent].MaximumRank),ref y);Place(state,available?"Disponible":reason,ref y);state.color=available?new Color(.94f,.8f,.55f):new Color(.8f,.49f,.36f);content.sizeDelta=new Vector2(300,Mathf.Max(478,y));learn.interactable=available;if(lastIndex!=index){content.anchoredPosition=Vector2.zero;lastIndex=index;}}
}
}
